import{c as s,Q as i,j as a,m as t}from"./chunks/framework.DGHXLY8X.js";const g=JSON.parse('{"title":"Monitoring a running deployment","description":"","frontmatter":{},"headers":[],"relativePath":"operating/observability.md","filePath":"operating/observability.md","lastUpdated":1780591920000}'),o={name:"operating/observability.md"};function n(d,e,l,r,c,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="monitoring-a-running-deployment" tabindex="-1">Monitoring a running deployment <a class="header-anchor" href="#monitoring-a-running-deployment" aria-label="Permalink to &quot;Monitoring a running deployment&quot;">​</a></h1><p>This page covers three operator tasks: scraping Prometheus metrics, consuming real-time SSE events, and filtering structured logs by entity ID.</p><h2 id="scraping-prometheus-metrics" tabindex="-1">Scraping Prometheus metrics <a class="header-anchor" href="#scraping-prometheus-metrics" aria-label="Permalink to &quot;Scraping Prometheus metrics&quot;">​</a></h2><p>VideoNode exposes a standard Prometheus text endpoint. To collect metrics, point your scrape config at <code>/metrics</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/metrics</span></span></code></pre></div><p>All metrics use the <code>videonode_</code> prefix. The families include:</p><ul><li><code>videonode_ffmpeg_*</code>: per-stream encoder stats (<code>fps</code>, <code>dropped_frames_total</code>, <code>duplicate_frames_total</code>, <code>processing_speed</code>), labeled by <code>stream_id</code></li><li><code>videonode_producer_*</code>: per-source process stats (<code>rss_bytes</code>, <code>cpu_percent</code>), labeled by <code>source_id</code></li><li><code>videonode_webrtc_*</code> and <code>videonode_srt_*</code>: egress byte and packet counters, labeled by <code>stream_id</code></li></ul><p>To see the full current set, scrape the endpoint directly; the list grows with the deployment.</p><h2 id="consuming-sse-events" tabindex="-1">Consuming SSE events <a class="header-anchor" href="#consuming-sse-events" aria-label="Permalink to &quot;Consuming SSE events&quot;">​</a></h2><p>To receive real-time lifecycle and status changes, connect to the single multiplexed SSE stream:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/events</span></span></code></pre></div><p>Each event carries a typed payload. The two you&#39;ll see most:</p><ul><li><code>entity</code>: a uniform envelope for every per-entity update, discriminated by <code>entity_type</code> (<code>source</code>, <code>composer</code>, <code>stream</code>) and <code>action</code> (<code>created</code>, <code>updated</code>, <code>deleted</code>, <code>status</code>, <code>metrics</code>, <code>consumers</code>)</li><li><code>pipeline-state-changed</code>: fires when the pipeline master switch toggles on or off</li></ul><p>The connection sends a <code>heartbeat</code> every 15 seconds to keep proxies and idle clients alive. For the full event model, see <a href="./../development/events-and-sse">Events and SSE</a>.</p><h2 id="filtering-logs-by-stream" tabindex="-1">Filtering logs by stream <a class="header-anchor" href="#filtering-logs-by-stream" aria-label="Permalink to &quot;Filtering logs by stream&quot;">​</a></h2><p>VideoNode writes structured logs via <code>slog</code>. Each log record&#39;s attributes map to uppercase journal fields.</p><p>To see all fields on recent records:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verbose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;5 min ago&quot;</span></span></code></pre></div><p>To filter records for one stream:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> STREAM_ID=rtsp-lobby</span></span></code></pre></div><p>To filter by module (e.g., the encoder pipeline):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MODULE=encoder</span></span></code></pre></div><p>To list every stream ID that has produced a log record:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> STREAM_ID</span></span></code></pre></div><p>Use <code>SOURCE_ID</code> and <code>COMPOSER_ID</code> in place of <code>STREAM_ID</code> for source and composer log records respectively.</p>',25)])])}const k=s(o,[["render",n]]);export{g as __pageData,k as default};
